for r in d['results']:
  for p in r['packages']:
    pk=p['package']
    fixed=set()
    for v in p['vulnerabilities']:
      for a in v.get('affected',[]):
        if a['package']['name'].lower()==pk['name'].lower():
          for rg in a.get('ranges',[]):
            for e in rg['events']:
              if 'fixed' in e: fixed.add(e['fixed'])
